CREATE TABLE public_content_page (
    id BIGINT NOT NULL AUTO_INCREMENT,
    slug VARCHAR(80) NOT NULL,
    title VARCHAR(160) NOT NULL,
    category VARCHAR(40) NOT NULL,
    country_code VARCHAR(10) NOT NULL,
    locale VARCHAR(20) NOT NULL DEFAULT 'en-US',
    version VARCHAR(80) NOT NULL,
    effective_date DATE NOT NULL,
    last_reviewed_at DATE NOT NULL,
    section_order INT NOT NULL,
    section_heading VARCHAR(200) NOT NULL,
    section_body TEXT NOT NULL,
    approved BOOLEAN NOT NULL DEFAULT TRUE,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id),
    CONSTRAINT uk_public_content_page_section UNIQUE (slug, country_code, locale, section_order),
    INDEX idx_public_content_page_lookup (slug, country_code, locale, approved, enabled),
    INDEX idx_public_content_page_category (category, approved, enabled)
);

