('about-us', 'About Us', 'Company', 'GLOBAL', 'en-US', 'global-about-us-2026.1', '2026-06-01', '2026-06-05', 1, 'Sharity', 'Sharity helps buyers and sellers complete marketplace transactions with protected payments, safer communication, and privacy-conscious account controls.', TRUE, TRUE),
('about-us', 'About Us', 'Company', 'GLOBAL', 'en-US', 'global-about-us-2026.1', '2026-06-01', '2026-06-05', 2, 'What we build', 'We support digital and physical commerce experiences where policy, identity, support, and trust tooling are part of the product from day one.', TRUE, TRUE),
('careers', 'Careers', 'Company', 'GLOBAL', 'en-US', 'global-careers-2026.1', '2026-06-01', '2026-06-05', 1, 'Build with us', 'Career openings will be published only after a role is approved for public posting.', TRUE, TRUE),
('careers', 'Careers', 'Company', 'GLOBAL', 'en-US', 'global-careers-2026.1', '2026-06-01', '2026-06-05', 2, 'Recruiting safety', 'Sharity does not ask candidates to buy equipment, share banking passwords, or continue hiring conversations outside approved channels.', TRUE, TRUE),
('press', 'Press', 'Company', 'GLOBAL', 'en-US', 'global-press-2026.1', '2026-06-01', '2026-06-05', 1, 'Media inquiries', 'Approved press materials and media contacts will appear here when available.', TRUE, TRUE),
('press', 'Press', 'Company', 'GLOBAL', 'en-US', 'global-press-2026.1', '2026-06-01', '2026-06-05', 2, 'Brand use', 'Do not use Sharity marks in a way that suggests sponsorship, endorsement, or partnership without written approval.', TRUE, TRUE),
('help-center', 'Help Center', 'Support', 'GLOBAL', 'en-US', 'global-help-center-2026.1', '2026-06-01', '2026-06-05', 1, 'Getting help', 'Sign in to view order-specific support. Public help articles explain account safety, buying, selling, payment authorization, refunds, and disputes.', TRUE, TRUE),
('help-center', 'Help Center', 'Support', 'GLOBAL', 'en-US', 'global-help-center-2026.1', '2026-06-01', '2026-06-05', 2, 'Account safety', 'Sharity support will never ask for your password, full payment credentials, or one-time sign-in codes.', TRUE, TRUE),
('safety', 'Safety', 'Support', 'GLOBAL', 'en-US', 'global-safety-2026.1', '2026-06-01', '2026-06-05', 1, 'Safer marketplace rules', 'Keep payments, delivery updates, digital-code handling, and support conversations inside Sharity.', TRUE, TRUE),
('safety', 'Safety', 'Support', 'GLOBAL', 'en-US', 'global-safety-2026.1', '2026-06-01', '2026-06-05', 2, 'Reporting', 'Report suspicious listings, unsafe messages, invalid digital access, or identity misuse from the relevant order or profile screen.', TRUE, TRUE),
('contact-us', 'Contact Us', 'Support', 'GLOBAL', 'en-US', 'global-contact-us-2026.1', '2026-06-01', '2026-06-05', 1, 'Support channels', 'Signed-in users should open support from their account or order. Guests can use public help topics until contact intake is enabled.', TRUE, TRUE),
('contact-us', 'Contact Us', 'Support', 'GLOBAL', 'en-US', 'global-contact-us-2026.1', '2026-06-01', '2026-06-05', 2, 'Sensitive information', 'Do not send passwords, raw digital codes, full card numbers, or government ID images through public contact channels.', TRUE, TRUE),
('privacy', 'Privacy Policy', 'Legal', 'US', 'en-US', 'us-privacy-2026.1', '2026-06-01', '2026-06-05', 1, 'Privacy by region', 'This United States privacy notice explains how Sharity handles account data, transaction data, device signals, support records, and safety reports.', TRUE, TRUE),
('privacy', 'Privacy Policy', 'Legal', 'US', 'en-US', 'us-privacy-2026.1', '2026-06-01', '2026-06-05', 2, 'Location and country', 'We may use trusted edge headers, browser locale, profile country, or IP-derived country signals to show relevant marketplace availability, policies, and legal notices.', TRUE, TRUE),
('privacy', 'Privacy Policy', 'Legal', 'US', 'en-US', 'us-privacy-2026.1', '2026-06-01', '2026-06-05', 3, 'Your choices', 'You can manage privacy settings, aliases, communication preferences, data export, and account deletion from account settings when signed in.', TRUE, TRUE),
('terms', 'Terms of Service', 'Legal', 'US', 'en-US', 'us-terms-2026.1', '2026-06-01', '2026-06-05', 1, 'Using Sharity', 'By using Sharity in the United States, you agree to follow marketplace rules, pay only through approved checkout, and provide accurate account information.', TRUE, TRUE),
('terms', 'Terms of Service', 'Legal', 'US', 'en-US', 'us-terms-2026.1', '2026-06-01', '2026-06-05', 2, 'Transactions', 'Orders, refunds, disputes, digital delivery, and seller payouts may be subject to country-specific eligibility, verification, and compliance requirements.', TRUE, TRUE),
('terms', 'Terms of Service', 'Legal', 'US', 'en-US', 'us-terms-2026.1', '2026-06-01', '2026-06-05', 3, 'Changes', 'Material legal changes may require re-acceptance before you continue using affected features.', TRUE, TRUE),
('terms', 'Terms of Service', 'Legal', 'CA', 'en-US', 'ca-terms-2026.1', '2026-06-01', '2026-06-05', 1, 'Terms of Service for CA', 'These terms apply to visitors detected in Canada. Local marketplace eligibility, consumer notices, tax handling, refunds, and payout requirements may differ from the United States version.', TRUE, TRUE),
